SELECT

FROM wms_sales_outbound_order o
LEFT JOIN sys_tenant t ON t.id = o.erp_tenant_id
LEFT JOIN sys_tenant op ON op.id = t.parent_wms_tenant_id
LEFT JOIN wms_warehouse w ON w.id = o.warehouse_id
LEFT JOIN wms_logistics_product lp ON lp.id = o.logistics_product_id


        AND o.outbound_no LIKE CONCAT('%', #{qo.outboundNo}, '%')


        AND o.erp_tenant_id = #{qo.erpTenantId}


        AND t.parent_wms_tenant_id = #{qo.wmsTenantId}


        AND DATE(o.create_time) >= #{qo.createTimeStart}


        AND DATE(o.create_time) <= #{qo.createTimeEnd}


        AND o.order_status IN
        #{st}


ORDER BY o.create_time DESC

SELECT
o.source_type = 'SALES' AND o.order_status IN ('PICKED', 'PACKED', 'SHIPPED', 'COMPLETED')
AND (p.platform_order_id LIKE CONCAT('%', #{qo.keyword}, '%') OR p.sort_code LIKE CONCAT('%', #{qo.keyword}, '%') OR p.sort_slot_scan_code LIKE CONCAT('%', #{qo.keyword}, '%'))
AND LOWER(p.platform) = LOWER(#{qo.platform})
AND p.pack_status = 'PENDING'
AND p.pack_status = 'PACKED' AND COALESCE(p.ship_status, 'PENDING') != 'SHIPPED'
AND COALESCE(p.ship_status, 'PENDING') = 'SHIPPED'
AND p.erp_tenant_id = #{qo.erpTenantId}
AND t.parent_wms_tenant_id = #{qo.wmsTenantId}
AND DATE(p.create_time) >= #{qo.createTimeStart}
AND DATE(p.create_time) <= #{qo.createTimeEnd}
ORDER BY FIELD(CASE WHEN COALESCE(p.ship_status, 'PENDING') = 'SHIPPED' THEN 'SHIPPED' WHEN p.pack_status = 'PACKED' THEN 'PACKED' ELSE 'PENDING_PACK' END, 'PENDING_PACK', 'PACKED', 'SHIPPED'), p.update_time DESC, p.id DESC
